-- Venue Live Guest "Ulang Tahun Carousel Impian". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara carousel), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'carousel', 'Ulang Tahun Carousel Impian', 'carousel', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 168, 'center 38%',
  $t${"name":"Carousel Impian","orn":"diamond","ui":{"ivory":"#FBF5FF","white":"#FFFFFF","soft":"#EBDDFB","soft2":"#CDB0F2","accent":"#9B6BD0","deep":"#5B3A8C","ink":"#45306B","mute":"#9A86B5","line":"#E3D3F5","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FEFAFF","ink":"#45306B","accent":"#9B6BD0","gold":"#C9A24A","leaf":"#EBDDFB","hbg":"rgba(251,245,255,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(69,48,107,.9)","acc":"#F7D3F0","on":"#45306B"},"scr":{"wine":"#5B3A8C","veil":"251,245,255"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'carousel');
